        $this->connector->send(new Request(
            Method::Get,
            '/whatsapp-flows/'.Payload::segment($definitionId),
        ));
    }

    /**
     * Update Wa Flow.
     *
     * Update metadata (name, description, categories) or archive / restore.
     *
     * The builder doc is saved via POST /{id}/versions.
     *
     * Scopes: whatsapp_flows:write.
     *
     * @param  list<string>|null  $categories
     * @param  ?string  $status  'archived' archives; 'active' restores
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/update_wa_flow_api_v1_whatsapp_flows__definition_id__patch
     */
    public function updateWa(
        string $definitionId,
        ?string $name = null,
        ?string $description = null,
        ?array $categories = null,
        ?string $status = null,
        ?string $idempotencyKey = null,
    ): void {
        $this->connector->send(new Request(
            Method::Patch,
            '/whatsapp-flows/'.Payload::segment($definitionId),
            body: Payload::body([
                'name' => $name,
                'description' => $description,
                'categories' => $categories,
                'status' => $status,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * Wa Flow Analytics.
