    /**
     * Clone Wa Flow.
     *
     * Copy the current version into a new flow (same or sibling workspace).
     *
     * Cross-workspace copies are limited to the same billing account and need whatsapp_flows:write in
     * the target workspace (checked by the service). API keys may only copy into another workspace
     * when the key itself holds tenants:manage; OAuth apps may only copy within the current workspace.
     *
     * Scopes: whatsapp_flows:write.
     *
     * @param  array<string, mixed>|null  $body  The request body
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/clone_wa_flow_api_v1_whatsapp_flows__definition_id__clone_post
     */
    public function cloneWa(string $definitionId, ?array $body = null, ?string $idempotencyKey = null): void
    {
        $this->connector->send(new Request(
            Method::Post,
            '/whatsapp-flows/'.Payload::segment($definitionId).'/clone',
            body: $body,
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * Compile Wa Flow.
