    /**
     * Preview Wa Flow Data.
     *
     * Entry-screen data a send would carry, per key with its source (nothing is sent).
     *
     * Same resolve + merge as a real send: initial_data (override) > saved channel defaults >
     * send-time bindings incl. default prefill > __example__. Without contact_id no contact data is
     * resolved (examples only). Values coming from the contact are returned verbatim, never
     * template-rendered.
     *
     * Response: {screen, data, sources: {<key>: "prefill"|"binding"|"override"|"example"}} (saved
     * channel defaults count as binding).
     *
     * Scopes: whatsapp_flows:read, contacts:read.
     *
     * @param  array<string, mixed>|null  $initialData  Per-send overrides (any data key, e.g. __prefill_<name>); win over everything.
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/preview_wa_flow_data_api_v1_whatsapp_flows__definition_id__preview_data_post
     */
    public function previewWaData(
        string $definitionId,
        ?string $contactId = null,
        ?string $channelId = null,
        ?array $initialData = null,
        ?string $idempotencyKey = null,
    ): void {
        $this->connector->send(new Request(
            Method::Post,
            '/whatsapp-flows/'.Payload::segment($definitionId).'/preview-data',
            body: Payload::body([
                'contact_id' => $contactId,
                'channel_id' => $channelId,
                'initial_data' => $initialData,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * List Wa Flow Publications.
