    /**
     * Push Wa Flow.
     *
     * Push a version to Meta as a DRAFT, one Meta flow per WhatsApp Business Account.
     *
     * channel_ids are grouped by WABA. Per-WABA failures are returned in errors when at least one WABA
     * succeeded; otherwise the error is raised.
     *
     * The version's builder doc is recompiled with the current compiler before upload (422
     * version_recompile_invalid with issues if it no longer validates). Imported flows are uploaded
     * byte-for-byte as stored.
     *
     * Scopes: whatsapp_flows:write.
     *
     * @param  list<string>  $channelIds
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/push_wa_flow_api_v1_whatsapp_flows__definition_id__publications_post
     */
    public function pushWa(
        string $definitionId,
        array $channelIds,
        ?string $versionId = null,
        ?string $idempotencyKey = null,
    ): void {
        $this->connector->send(new Request(
            Method::Post,
            '/whatsapp-flows/'.Payload::segment($definitionId).'/publications',
            body: Payload::body(['channel_ids' => $channelIds, 'version_id' => $versionId]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

    /**
     * Get Wa Flow References.
     *
     * Where this WhatsApp Flow is used (archive / publish-changes dialogs).
     *
     * * automations -- Send WhatsApp Flow nodes (and form-completed triggers, node_id: "trigger") of
     * this workspace's automations that reference it. * templates -- WhatsApp templates whose FLOW
     * button opens one of its Meta flows (current, still-live and superseded ids), ANY status (the
     * retirement check only counts APPROVED/PENDING -- template_refs_for_meta_flows). *
     * scheduled_sends_count -- scheduled sends never reference a flow definition directly (they go
     * through templates), so this is 0.
     *
     * Archiving never breaks these references; they keep working.
     *
     * Scopes: whatsapp_flows:read.
     *
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/get_wa_flow_references_api_v1_whatsapp_flows__definition_id__references_get
     */
    public function getWaReferences(string $definitionId): void
    {
        $this->connector->send(new Request(
            Method::Get,
            '/whatsapp-flows/'.Payload::segment($definitionId).'/references',
        ));
    }

    /**
     * Send Wa Flow.
     *
     * Send a published flow to a contact (interactive inside 24h, or via an approved template).
     *
     * initial_data string values may use contact variables ({{contact.first_name}}, {{contact.email}},
     * {{contact.custom.<key>}}, ...); they are rendered for the recipient before sending. Draft flows
     * cannot be sent (draft_send_not_supported).
     *
     * Custom Inboxes: a contact-addressed send by a member restricted to specific inboxes returns 409
     * conversation_owned_elsewhere while the contact is in an ongoing conversation a colleague handles
     * that the member cannot open.
     *
     * Scopes: messages:create, whatsapp_flows:read.
     *
     * @param  ?string  $mode  'interactive' (inside 24h window) or 'template'
     * @param  array<string, mixed>|null  $initialData  Entry-screen data. String values may contain contact variables such as {{contact.first_name}} or {{contact.custom.<key>}}, rendered per recipient.
     * @param  ?string  $flowAction  'navigate' | 'data_exchange' | omitted = auto
     * @param  ?string  $idempotencyKey  Repeat a request safely: SendSeven answers a repeat with the first result. One is generated when omitted.
     *
     * @throws ApiException
     *
     * @see https://api.sendseven.com/api/v1/docs#/WhatsApp%20Flows/send_wa_flow_api_v1_whatsapp_flows__definition_id__send_post
     */
    public function sendWa(
        string $definitionId,
        ?string $channelId = null,
        ?string $contactId = null,
        ?string $conversationId = null,
        ?string $mode = null,
        ?string $screen = null,
        ?array $initialData = null,
        ?string $headerText = null,
        ?string $bodyText = null,
        ?string $footerText = null,
        ?string $cta = null,
        ?string $templateId = null,
        mixed $templateVariables = null,
        ?bool $draft = null,
        ?string $flowAction = null,
        ?string $idempotencyKey = null,
    ): void {
        $this->connector->send(new Request(
            Method::Post,
            '/whatsapp-flows/'.Payload::segment($definitionId).'/send',
            body: Payload::body([
                'channel_id' => $channelId,
                'contact_id' => $contactId,
                'conversation_id' => $conversationId,
                'mode' => $mode,
                'screen' => $screen,
                'initial_data' => $initialData,
                'header_text' => $headerText,
                'body_text' => $bodyText,
                'footer_text' => $footerText,
                'cta' => $cta,
                'template_id' => $templateId,
                'template_variables' => $templateVariables,
                'draft' => $draft,
                'flow_action' => $flowAction,
            ]),
            headers: $idempotencyKey === null ? [] : ['Idempotency-Key' => $idempotencyKey],
        ));
    }

